  for (uint8_t i = 0; i < reg->num_qubits; i++) apply_gate_h(reg, i);
  for (uint8_t i = 0; i < reg->num_qubits; i++) apply_gate_x(reg, i);

  apply_multi_controlled_z(reg);

  for (uint8_t i = 0; i < reg->num_qubits; i++) apply_gate_x(reg, i);
  for (uint8_t i = 0; i < reg->num_qubits; i++) apply_gate_h(reg, i);
}

